questionvariables.text:
/* Five parallel statements, one per variant. Display strings are fixed so Maxima never reorders them. */
vF: rand([1, 2, 3, 4, 5]);
wordsL: ["three consecutive odd numbers", "four consecutive odd numbers", "three consecutive even numbers", "five consecutive odd numbers", "four consecutive even numbers"];
numsL: ["\\(2k + 1\\), \\(2k + 3\\) and \\(2k + 5\\)",
 "\\(2k + 1\\), \\(2k + 3\\), \\(2k + 5\\) and \\(2k + 7\\)",
 "\\(2k\\), \\(2k + 2\\) and \\(2k + 4\\)",
 "\\(2k + 1\\), \\(2k + 3\\), \\(2k + 5\\), \\(2k + 7\\) and \\(2k + 9\\)",
 "\\(2k\\), \\(2k + 2\\), \\(2k + 4\\) and \\(2k + 6\\)"];
sumL: ["\\((2k + 1) + (2k + 3) + (2k + 5)\\)",
 "\\((2k + 1) + (2k + 3) + (2k + 5) + (2k + 7)\\)",
 "\\(2k + (2k + 2) + (2k + 4)\\)",
 "\\((2k + 1) + (2k + 3) + (2k + 5) + (2k + 7) + (2k + 9)\\)",
 "\\(2k + (2k + 2) + (2k + 4) + (2k + 6)\\)"];
zeroL: ["1, 3 and 5", "1, 3, 5 and 7", "0, 2 and 4", "1, 3, 5, 7 and 9", "0, 2, 4 and 6"];
sumexpL: [6*k + 9, 8*k + 16, 6*k + 6, 10*k + 25, 8*k + 12];
mfacL: [3, 8, 6, 5, 4];
ta1L: [2*k + 3, k + 2, k + 1, 2*k + 5, 2*k + 3];
/* Diagnostic: the k-term divided by the factor, the constant not. */
dslipL: [2*k + 9, k + 16, k + 6, 2*k + 25, 2*k + 12];
words: wordsL[vF]; nums: numsL[vF]; sumw: sumL[vF]; zerow: zeroL[vF];
sumexp: sumexpL[vF]; mfac: mfacL[vF]; ta1: ta1L[vF]; dslip: dslipL[vF];
s_assert(is(ev(expand(mfac*ta1 - sumexp), simp) = 0), true);
s_assert(is(length(unique([ta1, dslip, sumexp, ta1 + 1])) = 4), true);
/* Reasons: the correct one third. */
optsW: [
 [wpos, false, "The number in the brackets is positive."],
 [weven, false, "The number in the brackets is even."],
 [wint, true, "The number in the brackets is an integer."],
 [weach, false, "Each of the numbers being added has this factor."]
];
/* (a) must show the division done: reject any division in the bracket (user decision 2026-11-16). */
has_div(ex) := if atom(ex) then false else if is(op(ex) = "/") then true else some(has_div, args(ex));
validate_nodiv(ex) := if has_div(ex) then "Carry out the division: write the bracket without a fraction." else "";
